public class MediaInsightsPipelineConfigurationFactory(string resourceName = null, Action<Humidifier.Chime.MediaInsightsPipelineConfiguration> factoryAction = null) : ResourceFactory<Humidifier.Chime.MediaInsightsPipelineConfiguration>(resourceName)
{

    internal List<InnerMediaInsightsPipelineConfigurationMediaInsightsPipelineConfigurationElementFactory> ElementsFactories { get; set; } = [];

    internal InnerMediaInsightsPipelineConfigurationRealTimeAlertConfigurationFactory RealTimeAlertConfigurationFactory { get; set; }

    protected override Humidifier.Chime.MediaInsightsPipelineConfiguration Create()
    {
        var mediaInsightsPipelineConfigurationResult = CreateMediaInsightsPipelineConfiguration();
        factoryAction?.Invoke(mediaInsightsPipelineConfigurationResult);

        return mediaInsightsPipelineConfigurationResult;
    }

    private Humidifier.Chime.MediaInsightsPipelineConfiguration CreateMediaInsightsPipelineConfiguration()
    {
        var mediaInsightsPipelineConfigurationResult = new Humidifier.Chime.MediaInsightsPipelineConfiguration
        {
            GivenName = InputResourceName,
        };

        return mediaInsightsPipelineConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Chime.MediaInsightsPipelineConfiguration result)
    {
        base.CreateChildren(result);

        result.Elements = ElementsFactories.Any() ? ElementsFactories.Select(x => x.Build()).ToList() : null;
        result.RealTimeAlertConfiguration ??= RealTimeAlertConfigurationFactory?.Build();
    }

} // End Of Class

